{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "It defines a classroom library as materials a teacher obtains by donation, purchase, or other means and makes available to students assigned to the teacher’s classes.",
      "rationale": "Captures acquisition by the teacher and availability to assigned students, but omits the requirement that the materials be made available in that teacher’s classroom."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "A school library collection would exclude course-curriculum materials and classroom-library materials.",
      "rationale": "States both exclusions but omits the affirmative definition covering materials made available to students by an LEA-operated school or public charter school."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "“Materials” would include books and other items and content in various formats, including digital applications and subscriptions.",
      "rationale": "Identifies books, applications, subscriptions, and varied formats, but replaces the remaining expressly enumerated categories, including video games, with unspecified other items."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "The bill also adds classroom libraries to specified references in other subsections of the cited law, without setting out those subsections’ full contents.",
      "rationale": "Conveys the addition of classroom-library references but does not identify § 49-6-3803(a), (f), and (g), whose substantive targets cannot otherwise be identified from the supplied bill."
    },
    {
      "proposition_id": "P5",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not mention deletion of § 49-6-3803(b)."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Each local board of education and public charter school governing body would have to adopt a policy for developing and reviewing both school library collections and classroom libraries.",
      "rationale": "Conveys the required policy, both responsible governing bodies, and coverage of school library collections and classroom libraries."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The policy would have to provide a way for teachers, and for parents or legal guardians of students with access to a classroom library, to review and refer its materials for evaluation.",
      "rationale": "Captures the required procedure, eligible participants, access condition, and review and referral of classroom-library materials."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "It would also have to give those parents and guardians multiple chances during the school year to view books in their student’s classroom library.",
      "rationale": "Conveys multiple viewing opportunities throughout the school year for the parents and guardians identified in the preceding sentence."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "The policy would have to prohibit teachers from knowingly or intentionally using a classroom library to get around the school’s library-collection policy. The bill gives as examples materials found by the state textbook and instructional materials quality commission to be inappropriate for the age and maturity of students who may access them, or materials found by the local board or charter-school governing body to be unsuitable for or inconsistent with the school’s educational mission.",
      "rationale": "Captures the knowing-or-intentional circumvention prohibition and both grounds for findings, but omits local boards and charter-school governing bodies as authorities that can also find materials age- and maturity-inappropriate."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "It would take effect upon becoming law.",
      "rationale": "States the effective-date trigger accurately."
    }
  ]
}
